1	import java.util.TreeMap;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Random;
5	/**
6	 * Class responsible for handling the simulation of the disease.
7	 *
8	 * @version 1.0
9	 */
10	public class DiseaseHandler
11	{
12	    
13	    /*///////////////////////////////////////////////////////////////
14	                                 CONSTANTS
15	    //////////////////////////////////////////////////////////////*/
16	    
17	    // cooldown before the animal achieves natural immunity
18	    private static final int DISINFECTION_DURATION = 5;
19	    private final Random rand = Randomizer.getRandom();
20	    private final Field field;
21	    
22	    /*///////////////////////////////////////////////////////////////
23	                                   STATE
24	    //////////////////////////////////////////////////////////////*/
25	    
26	    private TreeMap<Integer, Integer> count;
27	    private int currentStep;
28	    
29	    /*///////////////////////////////////////////////////////////////
30	                                CONSTRUCTOR
31	    //////////////////////////////////////////////////////////////*/
32	    
33	    /**
34	     * Creates a new disease handler
35	     * @param field The field to later get the animals per block and compute the density
36	     */
37	    public DiseaseHandler(Field field)
38	    {
39	        count = new TreeMap<>();
40	        this.field = field;
41	        currentStep = 0;
42	    }
43	    
44	    /*///////////////////////////////////////////////////////////////
45	                          DISEASE SIMULATION LOGIC
46	    //////////////////////////////////////////////////////////////*/
47	    
48	    /**
49	     * Returns the map of simulation step → infection count.
50	     */
51	    public TreeMap<Integer, Integer> getCount()
52	    {
53	        return count;
54	    }
55	
56	    /**
57	     * Simulates the disease by iterating through every block in the field, and computing the density of the number of ppl infected 
58	     * in the given block to determine the likelyhood of being infected in the block
59	     */
60	    public void simulateDiseaseStep()
61	    {
62	        // fetch the animal per blocks eg : [block1 : [animal1,animal2, animal3]. block 2: [animal1, animal 2, animal3]...]
63	        List<List<Animal>> blocks = field.getAnimalsPerBlock();
64	        int infectionCount = 0;
65	        currentStep++;
66	        for (List<Animal> block : blocks) {
67	            int densityIndex = 0;
68	            List<Animal> uninfectedAnimals = new ArrayList<>();
69	            for(Animal animal : block) {
70	                if(animal.getInfectionTimestamp() != null && currentStep - animal.getInfectionTimestamp() < DISINFECTION_DURATION) {
71	                    // increase the counter of number of animals infected within this block.
72	                    densityIndex++;
73	                    continue;
74	                }
75	                if(animal.getInfectionTimestamp() == null) {
76	                    uninfectedAnimals.add(animal);
77	                }
78	            }
79	            // compute probability of being infected.
80	            double pValue = (double)((double)densityIndex/(double)block.size());
81	            for(Animal animal : uninfectedAnimals) {
82	                double randNumber = rand.nextDouble();
83	                if(randNumber < pValue ) {
84	                    animal.setInfectionTimestamp(currentStep);
85	                }
86	            }
87	            infectionCount += densityIndex;
88	        }
89	        count.put(currentStep, infectionCount);
90	    }
91	}
